var DATA = {"mode": "specs", "name": "Signature Reference GPU", "codename": "JAH-G1", "shaders": 6144, "tmus": 192, "rops": 64, "mem_size": "16 GB", "mem_type": "GDDR6X", "bus": 256, "release": "2026"};
function show(k,v){console.log(k+": "+v);}
var m=DATA.mode;
if(m==="specs"){
  console.log("GPU: "+DATA.name+" ("+DATA.codename+")");
  show("Shaders / TMUs / ROPs",DATA.shaders+" / "+DATA.tmus+" / "+DATA.rops);
  show("Memory",DATA.mem_size+" "+DATA.mem_type+" / "+DATA.bus+"-bit");
  show("Released",DATA.release);
}else if(m==="sensors"){
  show("GPU temp",DATA.temp+" C");
  show("Hot spot",DATA.hotspot+" C");
  show("GPU clock",DATA.clock+" MHz");
  show("Memory clock",DATA.memclock+" MHz");
  show("GPU load",DATA.load+"%");
  show("Fan",DATA.fan+"% ("+DATA.fanrpm+" RPM)");
}else if(m==="fillrate"){
  show("Pixel fillrate",(Math.round(DATA.rops*DATA.clock/100)/10)+" GPixel/s ("+DATA.rops+" ROPs x "+DATA.clock+" MHz)");
  show("Texture fillrate",(Math.round(DATA.tmus*DATA.clock/100)/10)+" GTexel/s ("+DATA.tmus+" TMUs x "+DATA.clock+" MHz)");
}else if(m==="bandwidth"){
  show("Memory bandwidth",(Math.round(DATA.bus/8*DATA.gbps*10)/10)+" GB/s ("+DATA.bus+"-bit x "+DATA.gbps+" Gbps/pin)");
}else if(m==="advanced"){
  console.log("Advanced tab entries:");
  DATA.items.forEach(function(it){console.log("  "+it);});
}else if(m==="lookup"){
  show("Lookup","opens the TechPowerUp GPU database page for this card");
  show("Device ID",DATA.devid);
}else if(m==="rendertest"){
  show("Render test","renders a 3D load to force the max PCIe link state");
  show("Why","idle GPUs drop to fewer lanes to save power");
  show("Observed",DATA.lanes);
}else if(m==="bios"){
  show("BIOS version",DATA.bios);
  show("Saved to",DATA.file);
  show("Note","always back up the VBIOS before flashing");
}else if(m==="log"){
  show("Log file",DATA.file);
  show("Interval",DATA.ms+" ms");
  show("Use","graph temperature and clocks across a full run");
}else if(m==="clocks"){
  show("Base clock",DATA.base+" MHz");
  show("Boost clock",DATA.boost+" MHz");
  show("Current clock",DATA.cur+" MHz");
}else if(m==="memory"){
  show("Type",DATA.type);show("Size",DATA.size);
  show("Bus width",DATA.bus+"-bit");show("Bandwidth",DATA.bw);
}else if(m==="power"){
  show("Board power draw",DATA.w+" W");
  show("Power limit",DATA.limit+" W");
  show("PerfCap reason",DATA.perfcap);
}else if(m==="driver"){
  show("Driver",DATA.ver);
  show("Vulkan / OpenCL",DATA.vk+" / "+DATA.cl);
  show("WDDM",DATA.wddm);
}else if(m==="validation"){
  show("Validation","submit specs to TechPowerUp for a public proof link");
  show("Validation ID",DATA.valid);
}else if(m==="workflow"){
  console.log("Bench workflow:");
  DATA.steps.forEach(function(s,i){console.log("  "+(i+1)+". "+s);});
}
